#include "DasReflectedTypes.h"
#include "Dom/JsonObject.h"
#include "Serialization/JsonSerializer.h"
namespace {
bool TypeIdentifier(const FString& S){if(S.IsEmpty() || S.Len()>=NAME_SIZE || FChar::IsDigit(S[0]) || S.Equals(TEXT("None"),ESearchCase::IgnoreCase))return false;for(TCHAR C:S)if(!FChar::IsAlnum(C) && C!='_')return false;return true;}
bool TypeStable(const FString& S){if(S.IsEmpty() || S.Len()>256)return false;for(TCHAR C:S)if(!FChar::IsAlnum(C) && C!='_' && C!='.' && C!='-')return false;return true;}
bool TypeKeys(const TSharedPtr<FJsonObject>& J,std::initializer_list<const TCHAR*> Keys){for(const auto& P:J->Values){bool Found=false;for(const auto* K:Keys)Found |= FString(P.Key)==K;if(!Found)return false;}return true;}
bool TypeMeta(const TMap<FString,FString>& M){for(const auto& P:M)if((P.Key!=TEXT("DisplayName") && P.Key!=TEXT("ToolTip") && P.Key!=TEXT("Category")) || P.Value.Len()>4096)return false;return true;}
}
bool FDasReflectedTypes::Validate(FString& Error)const{
 Error.Reset();auto Fail=[&](const TCHAR* E){Error=E;return false;};if(!TypeStable(Id) || Enums.Num()+Structs.Num()==0 || Enums.Num()+Structs.Num()>256)return Fail(TEXT("Expected module ID and 1..256 reflected type declarations"));TSet<FString> IDs,Names;IDs.Add(Id);
 for(const auto& E:Enums){if(!TypeStable(E.Id) || IDs.Contains(E.Id) || !TypeIdentifier(E.Name) || Names.Contains(E.Name.ToLower()) || !TypeMeta(E.Metadata) || E.Entries.IsEmpty() || E.Entries.Num()>255)return Fail(TEXT("Invalid enum declaration identity/metadata/count"));IDs.Add(E.Id);Names.Add(E.Name.ToLower());TSet<FString> Members;TSet<int64> Values;for(const auto& V:E.Entries){if(!TypeIdentifier(V.Name) || V.Name.EndsWith(TEXT("_MAX"),ESearchCase::IgnoreCase) || Members.Contains(V.Name.ToLower()) || Values.Contains(V.Value) || V.Value<0 || V.Value>254)return Fail(TEXT("Enums require unique explicit byte values 0..254 and nonreserved names"));Members.Add(V.Name.ToLower());Values.Add(V.Value);}}
 for(const auto& S:Structs){if(!TypeStable(S.Id) || IDs.Contains(S.Id) || !TypeIdentifier(S.Name) || Names.Contains(S.Name.ToLower()) || !TypeMeta(S.Metadata) || S.Properties.IsEmpty() || S.Properties.Num()>64 || !S.Methods.IsEmpty())return Fail(TEXT("Invalid struct identity/metadata/field count"));IDs.Add(S.Id);Names.Add(S.Name.ToLower());FDasAuthoringModule Carrier;Carrier.Id=Id;auto C=S;C.NativeParent=TEXT("/Script/Engine.Actor");Carrier.Classes.Add(C);if(!Carrier.Validate(Error))return false;for(const auto& P:S.Properties){if(IDs.Contains(P.Id))return Fail(TEXT("Duplicate type/member stable ID"));IDs.Add(P.Id);if(P.bReadOnly || !P.bEditable)return Fail(TEXT("Initial user structs require editable read-write fields"));if(P.Type.Kind!=TEXT("int") && P.Type.Kind!=TEXT("float") && P.Type.Kind!=TEXT("double") && P.Type.Kind!=TEXT("bool") && P.Type.Kind!=TEXT("string") && P.Type.Kind!=TEXT("name"))return Fail(TEXT("Initial reflected structs support scalar/name fields only"));}}
 return true;
}
bool FDasReflectedTypes::ToJson(FString& Out,FString& Error)const{
 if(!Validate(Error))return false;auto Root=MakeShared<FJsonObject>();Root->SetNumberField(TEXT("schema_version"),1);Root->SetStringField(TEXT("module_id"),Id);TArray<TSharedPtr<FJsonValue>> ES,SS;
 for(const auto& E:Enums){auto J=MakeShared<FJsonObject>();J->SetStringField(TEXT("id"),E.Id);J->SetStringField(TEXT("name"),E.Name);auto Meta=MakeShared<FJsonObject>();TArray<FString> MetaKeys;E.Metadata.GetKeys(MetaKeys);MetaKeys.Sort();for(const auto& K:MetaKeys)Meta->SetStringField(K,E.Metadata[K]);J->SetObjectField(TEXT("metadata"),Meta);TArray<TSharedPtr<FJsonValue>> Entries;for(const auto& V:E.Entries){auto X=MakeShared<FJsonObject>();X->SetStringField(TEXT("name"),V.Name);X->SetNumberField(TEXT("value"),V.Value);Entries.Add(MakeShared<FJsonValueObject>(X));}J->SetArrayField(TEXT("entries"),Entries);ES.Add(MakeShared<FJsonValueObject>(J));}
 for(const auto& S:Structs){FDasAuthoringModule Carrier;Carrier.Id=Id;auto C=S;C.NativeParent=TEXT("/Script/Engine.Actor");Carrier.Classes.Add(C);FString Wire;if(!Carrier.ToJson(Wire,Error))return false;TSharedPtr<FJsonObject> Parsed;FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Wire),Parsed);auto J=Parsed->GetArrayField(TEXT("classes"))[0]->AsObject();J->RemoveField(TEXT("native_parent"));J->RemoveField(TEXT("methods"));SS.Add(MakeShared<FJsonValueObject>(J));}Root->SetArrayField(TEXT("enums"),ES);Root->SetArrayField(TEXT("structs"),SS);FString Result;FJsonSerializer::Serialize(Root,TJsonWriterFactory<>::Create(&Result));Out=MoveTemp(Result);return true;
}
bool FDasReflectedTypes::FromJson(const FString& Wire,FDasReflectedTypes& Out,FString& Error){
 Error.Reset();TSharedPtr<FJsonObject> J;if(Wire.Len()>1024*1024 || !FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Wire),J) || !J || !J->HasTypedField<EJson::Number>(TEXT("schema_version")) || J->GetNumberField(TEXT("schema_version"))!=1){Error=TEXT("Invalid reflected types JSON/version");return false;}FDasReflectedTypes C;if(!TypeKeys(J,{TEXT("schema_version"),TEXT("module_id"),TEXT("enums"),TEXT("structs")}) || !J->TryGetStringField(TEXT("module_id"),C.Id)){Error=TEXT("Missing reflected module ID");return false;}const TArray<TSharedPtr<FJsonValue>>* ES=nullptr,*SS=nullptr;if(!J->TryGetArrayField(TEXT("enums"),ES) || !J->TryGetArrayField(TEXT("structs"),SS)){Error=TEXT("Missing enum/struct arrays");return false;}
 for(const auto& V:*ES){const TSharedPtr<FJsonObject>* E=nullptr;if(!V->TryGetObject(E) || !TypeKeys(*E,{TEXT("id"),TEXT("name"),TEXT("metadata"),TEXT("entries")})){Error=TEXT("Expected enum object");return false;}FDasEnumDeclaration D;if(!(*E)->TryGetStringField(TEXT("id"),D.Id) || !(*E)->TryGetStringField(TEXT("name"),D.Name)){Error=TEXT("Missing enum identity");return false;}const TSharedPtr<FJsonObject>* M=nullptr;if(!(*E)->TryGetObjectField(TEXT("metadata"),M)){Error=TEXT("Missing enum metadata");return false;}for(const auto& P:(*M)->Values){FString S;if(!P.Value->TryGetString(S)){Error=TEXT("Expected string metadata");return false;}D.Metadata.Add(FString(P.Key),S);}const TArray<TSharedPtr<FJsonValue>>* Entries=nullptr;if(!(*E)->TryGetArrayField(TEXT("entries"),Entries)){Error=TEXT("Missing enum entries");return false;}for(const auto& X:*Entries){const TSharedPtr<FJsonObject>* Entry=nullptr;FDasEnumEntry N;double Number;if(!X->TryGetObject(Entry) || !TypeKeys(*Entry,{TEXT("name"),TEXT("value")}) || !(*Entry)->TryGetStringField(TEXT("name"),N.Name) || !(*Entry)->TryGetNumberField(TEXT("value"),Number) || !FMath::IsFinite(Number) || Number<0 || Number>254 || FMath::FloorToDouble(Number)!=Number){Error=TEXT("Invalid explicit enum value");return false;}N.Value=int64(Number);D.Entries.Add(N);}C.Enums.Add(D);}
 for(const auto& V:*SS){const TSharedPtr<FJsonObject>* S=nullptr;if(!V->TryGetObject(S)){Error=TEXT("Expected struct object");return false;}auto Copy=MakeShared<FJsonObject>();Copy->Values=(*S)->Values;Copy->SetStringField(TEXT("native_parent"),TEXT("/Script/Engine.Actor"));Copy->SetArrayField(TEXT("methods"),{});auto Root=MakeShared<FJsonObject>();Root->SetNumberField(TEXT("schema_version"),1);Root->SetStringField(TEXT("module_id"),C.Id);Root->SetArrayField(TEXT("classes"),{MakeShared<FJsonValueObject>(Copy)});FString Temp;FJsonSerializer::Serialize(Root,TJsonWriterFactory<>::Create(&Temp));FDasAuthoringModule Carrier;if(!FDasAuthoringModule::FromJson(Temp,Carrier,Error))return false;auto D=Carrier.Classes[0];D.NativeParent.Empty();C.Structs.Add(D);}if(!C.Validate(Error))return false;Out=MoveTemp(C);return true;
}
